  x = `Vous ne pouvez pas changer la catégorie d'une mise à jour importante associée à un message promotionnel.`,
  S = `Mise à jour de jeu`,
  C = `Informez votre communauté des nouvelles mises à jour, majeures ou mineures\xA0: nouveau contenu, changements apportés à des fonctionnalités ou corrections de bugs.`,
  w = `Invitez vos fans à discuter, à rencontrer les équipes de développement et à participer à une séance de questions et réponses.`,
  T = `Annoncez au public que votre jeu est maintenant disponible.`,
  E = `Encouragez la communauté à regarder des parties de votre jeu que ce soit un tournoi, une diffusion en direct de l'équipe de développement ou une session de streaming d'une chaine populaire.`,
  D = `Particulièrement indiqué pour les corrections et modifications mineures qui affectent une partie de vos joueurs et joueuses.`,
  O = `Particulièrement indiqué pour les mises à jour normales effectuées chaque semaine ou chaque mois.`,
  k = `Réservez ce genre d'évènements à vos mises à jour les plus importantes\xA0:\xA0généralement une fois par trimestre ou quelques fois dans l'année.`,
