  N = `Annoncez une promotion sur des articles qui pourraient intéresser les membres de la communauté qui jouent à votre jeu (par exemple\xA0: des items virtuels, de la monnaie virtuelle ou un DLC).`,
  P = `Annoncez quand on pourra gagner des points supplémentaires en jouant à votre jeu.`,
  F = `Annoncez qu'il sera possible de trouver un butin rare ou exceptionnel pendant une durée limitée, ou bien augmentez la disponibilité du butin en faisant participer vos joueurs et joueuses.`,
