  R = `Demandez à vos fans d'effectuer certaines actions pour participer à un concours\xA0: créer une image, proposer un article sur le Workshop ou participer à un mode multijoueur compétitif.`,
  z = `Invitez vos fans à vous rencontrer dans la vraie vie ou prévenez-les quand vous vous rendez dans un endroit sympa.`,
