  V = `Planifiez ou annoncez les détails de participation à une bêta.`,
  H = `Offre gratuite à durée limitée qui permet aux clients Steam d'essayer votre jeu, DLC ou contenu en jeu. Cela peut prendre la forme d'un weekend gratuit ou toute autre forme d'accès à durée limitée à du contenu.`,
  U = `Décrivez le lancement de votre nouveau passe de bataille ou de saison. Cela correspond généralement à une période de quelques semaines ou quelques mois qui s'accompagne de nouveaux contenus, avantages ou évènements secondaires.`,
  W = `Vous voulez parler d'un autre jeu que vous sortez, ou d'une autre plateforme sur laquelle votre jeu est disponible\xA0? Cette catégorie est la seule que vous devez utiliser si votre message concerne un jeu, une plateforme ou un magasin différents.`,
