  ae = `Pour les remises ou promotions sur votre jeu, vos DLC ou sur du contenu en jeu. Annoncez une remise sur le jeu à ceux qui ne le possèdent pas, ou informez ceux qui le possèdent d'une remise sur du contenu en jeu.`,
  oe = `Les remises sont en général cachées jusqu'à ce qu'elles commencent. Vous pouvez planifier une remise ici, ainsi que l'annonce et l'image qui l'accompagnent.`,
