  _t = `Steam Néo Fest\xA0:\xA0présentation rapide`,
  vt = `Utilisez cette section pour donner à la clientèle de Steam des informations intéressantes sur votre équipe de développement, le contenu de votre démo et ses liens avec votre jeu. Si cette section est remplie, elle sera affichée sur la page du magasin Steam de votre jeu et sur les pages Néo Fest où votre jeu apparait.`,
