  qt = `La programmation inclura toujours tout évènement du groupe de base qui remplit les conditions de participation ainsi que tous les évènements d'une série. En cochant cette case, vous permettez que n'importe quelle application mise en avant puisse avoir ses propres évènements admissibles annoncés dans la programmation. En décochant cette case, vous limitez les évènements autorisés exclusivement à ceux associés au groupe de la communauté organisateur ou ceux listés explicitement au sein d'une série.`,
