  Rr = `Rappels automatiques`,
  zr = `En programmant un évènement ET en le rendant visible de vos fans plus tôt, ils pourront choisir de recevoir un rappel au début de l'évènement. Steam leur enverra automatiquement une notification push et/ou un e-mail selon leurs préférences.`,
