  xa = `Publier comme évènement non répertorié`,
  Sa = `La publication de l'évènement enregistrera toutes les modifications et rendra l'évènement visible pour les personnes possédant l'hyperlien, même s'il n'apparait pas dans les listes d'évènements.`,
  Ca = `Publier`,
  wa = `La publication de la page enregistrera toutes les modifications et rendra la page de conception visible pour les personnes possédant l'hyperlien. Il faudra également l'activer après sa publication pour qu'elle serve de page de conception.`,
