  Ma = `Vous pourrez continuer à modifier le contenu de cette page après sa publication.`,
  Na = `(Valve uniquement) Puisque ce clan dispose d'un mappage de projet Crowdin, toute mise à jour sera automatiquement transmise à Crowdin à chaque publication. Cette fonctionnalité peut être désactivée manuellement à tout moment.`,
  Pa = `Date de publication personnalisée`,
  Fa = `Les heures de publication personnalisées doivent se situer entre maintenant et l'heure de début de l'évènement`,
  Ia = `Seulement pour les heures de publications personnalisées`,
  La = `Impossible de publier un évènement sans l'enregistrer d'abord`,
  Ra = `Approbation de Valve requise pour publier`,
  za = `Veuillez nous faire parvenir votre page à l'aide du bouton de droite au moins 7\xA0jours avant la date de publication souhaitée afin de laisser assez de temps pour que la page soit évaluée et approuvée, et pour que vous puissiez effectuer les éventuelles modifications nécessaires.`,
  Ba = `Une erreur interne de l'éditeur est survenue. Nous n'avons pas chargé les traductions. Les fonctions d'enregistrement et de publication ont été bloquées pour éviter toute perte de données.`,
  Va = `Attention\xA0:\xA0le contenu de l'annonce ou de l'évènement ont été modifiés à %1$s par %2$s. La version que vous avez commencé à modifier datait de %3$s. Voulez-vous remplacer ces modifications\xA0?`,
  Ha = `Voulez-vous remplacer ces modifications\xA0?`,
