  Ga = `État\xA0`,
  Ka = `Publication en cours, veuillez patienter...`,
  qa = `Ignorer les avertissements et continuer la publication...`,
  Ja = `Rendre visible du public immédiatement après la publication de l'évènement`,
  Ya = `Masquer jusqu'à l'heure de début de l'évènement définie plus haut`,
  Xa = `Masquer jusqu'à l'heure précisée ci-dessous...`,
  Za = `Cela signifie que les clients Steam pourront voir cet évènement dès que vous l'aurez publié. Il s'agit d'un choix par défaut pour les annonces ou les fonctionnalités publiées.`,
  Qa = `Cela signifie que l'évènement restera masqué jusqu'à son début. Il deviendra ensuite automatiquement visible.`,
  $a = `Après sa publication, votre évènement restera masqué jusqu'à l'heure spécifiée. Cela vous permet de préparer plusieurs évènements futurs et de les faire apparaitre automatiquement à l'heure spécifiée. Vous fournirez ainsi à vos clients un flux constant d'activités intéressantes.`,
  eo = `Masqué`,
