  io = `Cet évènement deviendra automatiquement visible par tous le %1$s`,
  ao = `Aucune autre action n'est requise.`,
  oo = `Après son enregistrement, cet évènement restera masqué. Pour rendre cet évènement visible par vos clients Steam, vous devez le publier.`,
  so = `Toutes les modifications de cet évènement que vous enregistrerez seront visibles par votre clientèle Steam.`,
