  bo = `Cet évènement est visible et a commencé le %1$s`,
  xo = `Cet évènement a été publié et rendu visible à %1$s`,
  So = `Modifier/déplacer`,
  Co = `Il s'agit d'une annonce qui a été créée dans une version antérieure du système d'annonce. Elle ne bénéficie pas des nouvelles catégories et n'a ni image principale ni date de fin. Si vous modifiez et enregistrez l'annonce, elle sera déplacée vers le nouveau système et\xA0les nouvelles fonctionnalités seront alors prises en charge.`,
  wo = `L'évènement sera supprimé de Steam ainsi que toutes ses métadonnées (votes, commentaires, statistiques). S'il est déjà visible, l'évènement redirigera vers une page vide et ne sera pas recommandé. Cette action est irréversible.`,
  To = `Vous permet de visualiser l'évènement comme les clients et clientes de Steam le verront. La barre d'aperçu située en haut vous permet de changer de langue facilement.`,
  Eo = `Cet évènement est associé à votre page d'accueil de conception\xA0: `,
