  Fo = `Ce créneau est déjà réservé par %1$s, vous ne pouvez donc pas programmer le début ou la fin d'un évènement pendant ce créneau. De même, vous ne pouvez pas programmer un évènement qui commence avant et se termine après le créneau réservé.`,
  Io = `Ce créneau est déjà réservé par %1$s (raison\xA0: %2$s). Vous ne pouvez donc pas programmer le début ou la fin d'un évènement pendant ce créneau. De même, vous ne pouvez pas programmer un évènement qui commence avant et se termine après le créneau réservé.`,
  Lo = `Fuseau horaire`,
