  Sh = `Filtrer une liste d'éditeurs ou une liste d'AppID est tout à fait optionnel. Si aucun des deux filtres n'est appliqué, nous comparerons les paramètres ci-dessus avec les autres éditeurs de Steamworks.`,
  Ch = `* Langue affichée\xA0:\xA0%1$s`,
