  Oh = `Endroits facultatifs`,
  kh = `Expositions`,
  Ah = `Magasin\xA0: sur la page de votre jeu`,
  jh = `Cet évènement apparaitra sur la page du magasin de votre jeu dans la section «\xA0Actualités et évènements\xA0».`,
  Mh = `Le nombre estimé de personnes visitant votre page du magasin au cours de l'évènement sera affiché ici.`,
  Nh = `Magasin\xA0: sur la page «\xA0Mis à jour récemment\xA0»`,
  Ph = `Si vous utilisez un cycle de visibilité de mise à jour, cet évènement apparaitra sur la page «\xA0Mis à jour récemment\xA0» pour les joueurs et joueuses qui possèdent votre jeu ou l'ont ajouté à leur liste de souhaits.`,
  Fh = `Le nombre qui s'affiche ici est le nombre de personnes qui possèdent votre jeu ou l'ont ajouté à leur liste de souhaits et qui voient votre jeu sur leur page «\xA0Mis à jour récemment\xA0».`,
