  Wh = `Bientôt\xA0:`,
  Gh = `Bibliothèque\xA0: sur la page d'accueil (potentiellement)`,
  Kh = `Vos joueurs et joueuses peuvent voir cet évènement en haut de la page d'accueil de leur bibliothèque, en fonction du nombre d'autres jeux qu'ils possèdent et des priorités relatives des annonces ou mises à jour.`,
  qh = `(en attente de modération)`,
  Jh = `Bibliothèque\xA0: bannière «\xA0coup de projecteur\xA0» sur la page de votre jeu`,
  Yh = `Si vous fournissez une image pour la bannière «\xA0coup de projecteur\xA0», votre évènement ou annonce peut apparaitre juste en dessous du bouton «\xA0Jouer\xA0» sur la page d'informations de votre jeu dans la bibliothèque Steam.`,
  Xh = `Bibliothèque\xA0: sur la page de votre jeu dans la bibliothèque Steam des joueurs et joueuses`,
  Zh = `Votre évènement apparaitra dans la section «\xA0Activité\xA0» de votre jeu dans la bibliothèque Steam de vos joueurs et joueuses.`,
  Qh = `D'après le nombre de joueurs et joueuses qui possèdent votre jeu et le voient dans leur bibliothèque Steam.`,
  $h = `Sur la page du Workshop`,
  eg = `Vous pouvez aussi publier cet évènement ou cette annonce sur le Workshop de votre jeu. Pour activer cette option, passez sur l'onglet «\xA0options\xA0» et sélectionnez «\xA0Publier également sur votre Workshop\xA0?\xA0». Par défaut, les évènements ou annonces de jeu n'apparaissent pas sur le Workshop.`,
  tg = `Bannière de la page Steam du produit`,
  ng = `Bannière de la page du produit visible du %1$s au %2$s`,
  rg = `Vous pouvez fournir une bannière promotionnelle dans l'onglet des promotions. Celle-ci apparaitra en haut de la page du magasin Steam des jeux en vedette et renverra le public vers la page promotionnelle. Ainsi, les personnes qui découvrent une remise sur un jeu via leur liste de souhaits ou en parcourant le magasin seront également informées plus largement de l'évènement promotionnel. Ces bannières ne sont visibles qu'entre le début et la fin de votre évènement ou jusqu'à deux semaines, selon le cas de figure qui se réalise en premier. Les dates et heures de début et de fin des évènements sont précisées dans l'onglet «\xA0Options\xA0».`,
  ig = `notification envoyée par e-mail aux personnes qui suivent votre jeu, ou l'équipe de développement ou d'édition`,
  ag = `Ceci comprend toutes les personnes abonnées aux pages de l'équipe de développement associées à ce jeu, à celles de l'équipe d'édition ou à celles de la franchise.`,
  og = `Les liens suivants vers l'équipe de développement, d'édition ou la franchise n'ont pas de page d'accueil de conception visible. Créez-en une pour aider le public à comprendre vos offres et le tenir au courant de vos évènements et de la sortie de nouveaux jeux\xA0: %1$s`,
  sg = `Actualités\xA0: calendrier des évènements personnalisés`,
  cg = `Cet évènement sera affiché dans le hub d'actualités personnalisé des joueurs et joueuses qui possèdent votre jeu dans leur bibliothèque, qui l'ont ajouté à leur liste de souhaits ou qui le suivent.`,
  lg = `Notifications\xA0: notifications push pour les joueurs et joueuses qui ont choisi cette option`,
  ug = `Nombre de joueurs et joueuses qui ont explicitement choisi d'avoir un rappel pour cet évènement (ont téléchargé un calendrier externe ou ont choisi de suivre cet évènement).`,
  dg = `personnes ont reçu un e-mail`,
  fg = `Estimation du nombre d'e-mails qui mentionnent cet évènement. Nous créons régulièrement un résumé personnalisé des évènements pour chaque client. Cela dépend des préférences de chaque utilisateur vis-à-vis des e-mails et des communications.`,
  pg = `personnes ont reçu un message promotionnel`,
  mg = `Estimation du nombre de personnes qui verront cet évènement dans leur message promotionnel personnalisé dans le client Steam. Il s'agit d'une fenêtre contextuelle qui apparait au lancement du client de bureau Steam. Cette fenêtre affiche les offres Steam pertinentes et des informations intéressantes sur les évènements.`,
  hg = `personnes ont ignoré cet évènement`,
