  vg = `Consulter la documentation`,
  yg = `Évaluation de message promotionnel de mise à jour importante`,
  bg = `Une fois que l'évènement est terminé et que plus aucune modification n'est nécessaire, veuillez l'envoyer pour évaluation dans le cadre d'une utilisation au sein d'un message promotionnel. Libre à vous de publier l'évènement de mise à jour importante dès qu'il est prêt. Veuillez prévoir jusqu'à %1$s\xA0jours ouvrables pour l'évaluation et l'approbation.`,
  xg = `Créez la demande suivante pour démarrer le processus d'évaluation.`,
  Sg = `Créer la demande d'évaluation`,
  Cg = `Demande envoyée. Veuillez vérifier et mettre à jour les informations <1>ici</1>.`,
  wg = `résumé`,
  Tg = `Début de la visibilité\xA0`,
  Eg = `Ce contenu sera visible dans la plupart des emplacements dès sa publication.`,
  Dg = `Remarque\xA0: les nouvelles annonces sont évaluées par notre équipe de modération selon leur ordre de publication. Un délai d'une heure ou plus peut s'écouler avant que l'actualité ou l'évènement n'apparaisse dans la bibliothèque Steam. Si vous modifiez une annonce existante, celle-ci sera à nouveau placée au bout de la file d'attente de modération.`,
  Og = `Ou bien, remplacer le contenu de l'évènement existant`,
  kg = `Rare. Permet d'organiser les mises à jour dans une sorte d'évènement «\xA0brouillon\xA0», puis de remplacer le contenu d'un évènement publié existant par le contenu de cet évènement «\xA0brouillon\xA0». Ce dernier disparaitra et son contenu remplacera l'évènement publié ciblé. Le type d'évènement et les paramètres de visibilité de l'évènement cible ne seront pas mis à jour.`,
  Ag = `Cet évènement a été dupliqué à partir de\xA0: «\xA0%1$s\xA0»`,
  jg = `Remplacer dans l'évènement original`,
