  t_ = `Vidéo d'avant-programme`,
  n_ = `Obsolète\xA0: le pipeline\xA0VOD est désormais désactivé et conservé uniquement à des fins de compatibilité avec les anciennes vidéos. Cette vidéo apparaitra dans le lecteur vidéo avant la programmation normale. Le fichier\xA0VOD doit disposer des permissions pour être visible du public (indépendamment de son état de publication).`,
