  L_ = `Facultatif\xA0: fournissez un évènement Steam qui décrit le détail des récompenses. Utile pour les évènements promotionnels qui ne proposent pas de texte de description.`,
  R_ = `ID de compte du clan`,
  z_ = `GID d'évènement du clan`,
  B_ = `Zones de diffusion élargies`,
  V_ = `Si elle est activée, cette option supprime les bandes à gauche et à droite de la fenêtre de diffusion. Cela n'est utile que dans le cas d'une diffusion unique où ces bandes risquent d'être source de distraction.`,
  H_ = `Activer le mode de diffusion large`,
  U_ = `Quand cette option est activée, le bouton pour afficher et masquer le chat apparait. Quand le chat est visible, la diffusion retrouve sa taille normale (pas large). Quand il est masqué, la diffusion est élargie.`,
  W_ = `Permettre de masquer le chat`,
  G_ = `Afficher les annonces des gagnants et gagnantes du concours`,
  K_ = `ID du concours`,
  q_ = `S'il y a un concours associé à la diffusion qui annonce les gagnants et les gagnantes sur le chat de la diffusion, l'établissement d'un ID de concours permet de récupérer les messages du chat même après fermeture de celui-ci, et ainsi de relire les annonces avec les noms des personnes gagnantes.`,
  J_ = `Titre de la diffusion`,
  Y_ = `Sélectionnez un titre parmi une liste de titres par défaut à afficher au-dessus de votre diffusion sur votre page du magasin, ou saisissez un titre personnalisé.`,
  X_ = `Saisissez un titre`,
  Z_ = `Consulter la documentation`,
  Q_ = `Image de la diffusion`,
  $_ = `Options de l'image de la diffusion`,
  ev = `Afficher les bannières droites et gauches au lieu de la capsule du jeu.`,
  tv = `Quand cette option est activée, la bannière remplacera les capsules du jeu sur le magasin Steam. Cela est utile quand la bannière donne davantage d'informations sur l'évènement que la ou les capsules de l'application. Quand plusieurs jeux sont diffusés au cours de l'évènement, cela vous permet également de n'afficher qu'une seule image pour l'évènement.`,
  nv = `Liste blanche de diffusion`,
  rv = `L'ID Steam indiqué n'est pas valide. Il doit correspondre à une valeur numérique de 64 bits.`,
  iv = `Arrière-plan de la diffusion`,
  av = `Couleur intérieure du dégradé de l'arrière-plan`,
  ov = `Couleur extérieure du dégradé de l'arrière-plan`,
  sv = `Échec du chargement des informations de l'utilisateur`,
  cv = `Il s'agit d'un paramètre facultatif qui permet d'indiquer que la diffusion doit être dans une certaine langue. Ainsi, si plusieurs diffusions retransmettent l'évènement dans différentes langues, nous pouvons présenter à chaque personne la diffusion par défaut la mieux adaptée en fonction de sa langue.`,
  lv = `Priorité`,
  uv = `Définissez la priorité de cette diffusion par rapport aux autres. Les diffusions dont la priorité est la plus élevée seront sélectionnées en premier. Si plusieurs diffusions ont la même priorité, celle par défaut sera sélectionnée au hasard.`,
  dv = `Principale (priorité absolue)`,
  fv = `À la une (priorité élevée)`,
  pv = `Par défaut (priorité moyenne)`,
  mv = `Général (basse priorité)`,
  hv = `Type de contenu diffusé`,
  gv = `Veuillez indiquer si le contenu est diffusé en direct ou s'il a été enregistré. Dans le second cas, veuillez préciser s'il s'agit d'une première diffusion sur la plateforme ou d'une rediffusion.`,
  _v = `Inconnu/non spécifié`,
  vv = `Diffusion en direct`,
  yv = `Première diffusion`,
