  Cv = `Contrôles de diffusion`,
  wv = `Contrôles de diffusion`,
  Tv = `ID de la partie`,
  Ev = `Mise à jour effectuée`,
  Dv = `Échec de la mise à jour, réessayez plus tard`,
  Ov = `La diffusion a été arrêtée`,
  kv = `Échec de l'arrêt de la diffusion, réessayez plus tard`,
  Av = `Arrêter la diffusion`,
  jv = `À propos de ce jeu\xA0`,
  Mv = `Page du magasin`,
  Nv = `Signaler la diffusion`,
  Pv = `Signalez cette diffusion.`,
  Fv = `FAQ sur les diffusions`,
  Iv = `Consultez la FAQ sur les diffusions.`,
  Lv = `Envoyer un avis`,
  Rv = `Signaler cette diffusion`,
  zv = `Veuillez indiquer la raison pour laquelle vous considérez que cette diffusion ne respecte pas les conditions d'utilisation de Steam. Veuillez inclure toute information ou tout lien pertinent. L'envoi de ce signalement est irréversible.`,
  Bv = `Programmation`,
  Vv = `Créateur de programmation`,
  Hv = `Créer une programmation ou un calendrier à afficher sur la page de vos évènements\xA0?`,
  Uv = `Ajouter une entrée à la programmation`,
  Wv = `Supprimer cette entrée`,
  Gv = `Prévisualisation de la programmation intégrée`,
  Kv = `Légende des types d'entrées de la programmation`,
  qv = `Type`,
  Jv = `Objectif`,
  Yv = `Partie contre`,
  Xv = `Il s'agit d'un match compétitif entre deux personnes/équipes ou plus. Une fois le match terminé, vous pouvez mettre à jour les résultats pour ajouter les informations du gagnant.`,
  Zv = `Diffusion`,
  Qv = `Incitez le public à regarder une diffusion en direct sur Steam ou ailleurs pendant cette période.`,
  $v = `Jouer`,
  ey = `Demandez à vos fans de se joindre à l'évènement à l'heure indiquée en lançant votre jeu et en y jouant.`,
  ty = `In Real Life`,
  ny = `Utilisé quand l'élément du programme se produit et n'est accessible qu'à ceux qui sont présents lors de l'évènement (il ne peut être diffusé en direct). Remarque\xA0: il vaut peut-être mieux ne pas inclure ceci dans la programmation puisque vos fans Steam ne peuvent pas y participer.`,
  ry = `Heure de début`,
  iy = `Durée en minutes avant le début de l'évènement`,
  ay = `minutes`,
  oy = `Cette entrée de la programmation n'est plus à sa valeur par défaut. Voulez-vous vraiment la supprimer\xA0? Vous ne pourrez pas revenir en arrière.`,
  sy = `Séries actuelles`,
  cy = `Une série lie un ensemble d'évènements connexes avec une image de marque et un thème de couleur communs. Les évènements ne doivent pas nécessairement apparaitre sur le même programme. Exemples\xA0: séries prestige ou art.`,
  ly = `Pas de série définie.`,
  uy = `Ajouter une série`,
  dy = `Ajoute une nouvelle série pour regrouper des évènements dans le programme et leur attribuer une marque commune.`,
  fy = `Supprimer la série`,
  py = `Voulez-vous vraiment supprimer cette série\xA0?`,
  my = `Piste sans nom\xA0:\xA0%1$s`,
  hy = `Ajoute des évènements pour cette série spécifique. Pour être valides, ils doivent être publiés, commencer et se terminer dans les périodes programmées et leur genre doit correspondre à celui de la programmation.`,
  gy = `Accords sur les évènements promotionnels`,
  _y = `Avant d'utiliser les outils d'édition de page promotionnelle, vous devez accepter les conditions ci-après.`,
  vy = `Je comprends que la page promotionnelle doit clairement identifier le groupe ou les individus chargés d'organiser la promotion ou l'évènement.`,
  yy = `Je comprends que je ne peux pas garantir aux jeux participants un quelconque niveau de visibilité sur Steam, et ne peux facturer le moindre emplacement sur la page de l'évènement promotionnel.`,
  by = `Je comprends que Valve se réserve le droit de modifier une page promotionnelle en changeant, entre autres, la visibilité des jeux ou des diffusions sur la page, ou les textes ou les images qui décrivent l'évènement.`,
  xy = `Je comprends que Valve choisit quels évènements promouvoir sur le magasin Steam et qu'il se peut que mon évènement ne soit pas mis en avant.`,
  Sy = `Je comprends que je ne peux ajouter à la page promotionnelle que les titres pour lesquels j'ai reçu l'autorisation de l'équipe de développement ou d'édition. L'équipe de développement recevra une notification dès que son titre aura été ajouté à la page.`,
  Cy = `J'accepte toutes les règles stipulées dans la %1$s.`,
  wy = `Consultez %1$s pour plus de détails sur la conception et la mise en forme d'une page promotionnelle.`,
  Ty = `cette page de la documentation`,
  Ey = `Contact principal`,
  Dy = `Je fais partie d'une équipe de développement ou d'édition, ou je suis journaliste, et j'ai des questions à propos de cet évènement. Qui devrais-je contacter\xA0?`,
  Oy = `saisissez un nom`,
  ky = `saisissez une adresse e-mail`,
