  Ly = `Vous avez lu et accepté les règles.`,
  Ry = `Veuillez fournir l'URL et le nom de l'entité organisatrice de cet évènement. Ces informations s'afficheront en haut de votre page promotionnelle.`,
  zy = `Organisation de l'évènement`,
  By = `Modifier les entités organisatrices de l'évènement`,
  Vy = `Saisir les détails de l'organisme`,
  Hy = `Veuillez fournir le nom de l'organisme qui a organisé cet évènement. Le lien peut rediriger vers la page d'accueil de conception sur Steam ou vers un site externe. Le nom doit être fourni en utilisant l'alphabet latin, mais il est possible d'inclure aussi la version d'origine.`,
  Uy = `Ces informations s'afficheront sur votre page promotionnelle de la manière suivante\xA0:`,
  Wy = `Ajouter une entité organisatrice`,
  Gy = `Nom de l'entité organisatrice`,
  Ky = `Adresse URL`,
  qy = `Groupe d'images traduites`,
  Jy = `Image principale du groupe des images localisées`,
  Yy = `Cette image sera utilisée s'il n'existe aucune version localisée de l'image dans la langue de l'utilisateur. Vous pouvez utiliser une image sans texte ou dans une langue parlée par tous vos clients.`,
  Xy = `Si votre image contient du texte, vous pouvez importer des versions traduites de cette image ici pour toutes les langues prises en charge par Steam. Steam affichera automatiquement l'image traduite appropriée à votre clientèle.`,
  Zy = `Téléchargez des images dont le nom se termine par %1$s de Steam pour qu'elles soient automatiquement associées à la langue en question.`,
  Qy = `un des codes de langue de l'API\xA0Web`,
  $y = `Images`,
  eb = `Utilisez la section située ci-dessous pour mettre en ligne de nouvelles images accessibles pour tous vos évènements. Vous pouvez faire glisser et déposer des images depuis cette section ou cliquer pour intégrer des images miniatures ou à taille réelle à votre publication.`,
