  dS = `Voulez-vous supprimer cette image du titre de l'évènement pour la langue de localisation\xA0: %1$s\xA0?  Ceci n'efface pas l'image sous-jacente mais supprime l'association à l'évènement.`,
  fS = `Le rectangle rouge sur votre image indique l'espace dans lequel votre logo et le texte doivent s'insérer. Cette sous-zone sera affichée dans certains contextes comme les listes d'évènements.`,
  pS = `Exemple de vue compacte`,
  mS = `Cette version recadrée de l'image sera utilisée dans les grilles ou les rangées de plusieurs évènements.`,
  hS = `Exemple d'utilisation sur la page des détails`,
  gS = `L'intégralité de l'image sera utilisée en haut de la page de détails de l'évènement.`,
  _S = `Les évènements s'affichent dans le calendrier\xA0!`,
  vS = `Les évènements s'affichent dans le résumé hebdomadaire\xA0!`,
  yS = `Les évènements s'affichent dans la bibliothèque\xA0!`,
