  XD = `Recommandations et listes d'un groupe de curation`,
  ZD = `Cette option permet de modifier la position sur la page où apparaitront la liste et les recommandations d'un groupe de curation. Par défaut, les personnes qui suivent le groupe de curation Steam voient ses recommandations de jeux à la une en bas de la page promotionnelle. Vous pouvez choisir l'emplacement de cette section.`,
