  $D = `Facultatif\xA0: heure de début de l'affichage`,
  eO = `Indiquez (facultatif) l'heure à partir de laquelle la recommandation apparaitra. Cela peut laisser le temps aux groupes de curation de créer leurs listes avant leur affichage. Cette heure doit se situer entre le début et la fin de l'évènement.`,
