  QW = `Type de section promotionnelle inconnu`,
  $W = `Cette section comporte seulement une image, souhaitez-vous plutôt la <1>convertir</1> en section d'image de titre\xA0?`,
  eG = `Les sections d'images facilitent la traduction d'une image, son rendu est également plus rapide sur la page promotionnelle qui s'affichera auprès de la clientèle. De plus, les images utilisées dans l'entête n'encombreront pas le sélecteur d'images.`,
  tG = `Prévisualisation du contenu partagé sur les réseaux sociaux`,
  nG = `Il s'agit d'un aperçu du contenu qui s'affichera lorsque l'évènement sera mis en lien ou partagé sur les réseaux sociaux.`,
  rG = `(Le titre utilisé est celui de l'évènement)`,
  iG = `(Le titre utilisé correspond à celui de la page d'accueil de conception par défaut)`,
  aG = `(La description utilisée est celle du résumé de l'évènement ou une description générée automatiquement.)`,
  oG = `(La description utilisée correspond à celle de la page d'accueil de conception par défaut)`,
  sG = `Image par défaut de la page pour les réseaux sociaux (générée à partir de l'image de l'évènement)\xA0: `,
  cG = `Pour personnaliser le contenu, accédez à la section «\xA0Éditeur de partage sur les réseaux sociaux\xA0».`,
  lG = `Afficher l'option «\xA0Partager avec vos contacts\xA0» (activée par défaut)`,
  uG = `Le contenu par défaut pour les réseaux sociaux a été remplacé par celui indiqué dans la section «\xA0Éditeur de partage sur les réseaux sociaux\xA0».`,
  dG = `Facultatif\xA0: ajoutez des liens vers les réseaux sociaux liés à la page d'accueil et à l'évènement. Ils s'afficheront de manière standard pour toute la clientèle.`,
  fG = `Activer les liens vers les réseaux sociaux`,
  pG = `Pas de liens vers les réseaux sociaux`,
  mG = `Bouton «\xA0Voir d'autres produits\xA0»`,
  hG = `Afficher le bouton «\xA0Voir d'autres produits\xA0» en bas de la page`,
  gG = `Voir d'autres produits`,
  _G = `Texte du bouton «\xA0Parcourir d'autres produits\xA0»`,
  vG = `URL du bouton «\xA0Parcourir d'autres produits\xA0»`,
  yG = `Couleur du bouton «\xA0Parcourir d'autres produits\xA0»`,
  bG = `Couleur de l'arrière-plan du bouton «\xA0Parcourir d'autres produits\xA0»`,
  xG = `Sections promotionnelles personnalisées`,
  SG = `Contenu de la page`,
  CG = `Rechercher`,
  wG = `Arrière-plan et image de la page promotionnelle`,
  TG = `Arrière-plan de la page`,
  EG = `Tout supprimer`,
  DG = `Supprime tous les articles de la liste ci-dessus`,
  OG = `Éditer les données brutes`,
  kG = `Cette option permet de modifier la liste d'articles liés à cet évènement promotionnel. Elle peut également être utilisée pour importer ou exporter des données depuis des outils comme Excel, ou encore pour effectuer rapidement des changements à grande échelle sur la liste d'articles.`,
  AG = `Étiquettes personnalisées`,
  jG = `Cette option vous permet de modifier directement la liste des articles liés de cette promotion, ainsi que d'importer et d'exporter une collection personnalisée d'étiquettes pour les articles en promotion. On l'utilise généralement pour importer une sélection d'étiquettes personnalisées qui proviennent d'un tableur externe sans modifier les autres étiquettes appliquées aux articles. De plus, il est possible d'importer un sous-ensemble d'étiquettes grâce à cette fenêtre de dialogue, car les articles non affichés ne seront pas supprimés.`,
  MG = `Importer depuis la page d'inscription`,
  NG = `Cette option ouvre une fenêtre qui permettra d'importer toutes les applications depuis une page d'inscription vers la liste des articles liés.`,
  PG = `Synchroniser les articles`,
  FG = `Synchroniser les étiquettes de démo`,
  IG = `Cette option permet de parcourir tous les articles liés et d'ajouter l'étiquette «\xA0HasDemo\xA0» (avec démo) à toutes les applications ayant une démo et de l'enlever à celles qui n'en ont pas.`,
  LG = `Synchroniser`,
  RG = `Cette option vous permet de synchroniser diverses étiquettes et d'autres informations entre les articles liés et d'autres sources.`,
  zG = `Synchroniser les étiquettes de démo`,
  BG = `Modifier les étiquettes automatiques`,
  VG = `Saisir un nom d'étiquette`,
  HG = `Il s'agit du nom de l'étiquette qui sera appliquée à tous les articles liés qui correspondent au filtre associé.`,
  UG = `Modifier le filtre d'articles (%1$s\xA0filtres)`,
  WG = `Modifier le filtre d'articles (%1$s\xA0filtres\xA0; %2$s\xA0articles filtrés)`,
  GG = `Cette option permet de mettre en place un filtre qui sera appliqué à tous les articles liés avant même de prendre en compte les sections. Vous pouvez par exemple exclure les jeux n'ayant pas de démo ou bien inclure uniquement les jeux ayant l'étiquette de votre choix.`,
  KG = `Explorer`,
  qG = `Cette option permet d'utiliser le filtre pour parcourir les articles actuellement configurés avec des étiquettes, déterminer combien d'entre eux répondent aux critères des différents filtres ou identifier les étiquettes qui leur sont associées.`,
  JG = `Modification en masse`,
  YG = `Cette option permet de modifier en masse les articles avec étiquette. Vous pouvez fournir une liste d'articles pour lesquels les étiquettes seront ajoutées ou retirées de manière groupée.`,
  XG = `Étiquettes automatiques`,
  ZG = `Cette option permet de créer des étiquettes automatiques\xA0: il s'agit d'un filtre qui applique l'étiquette à tout article lié qui correspond à ses critères.`,
  QG = `Affichage des articles`,
  $G = `Affiche les articles (exclure les articles filtrés)`,
