  tK = `Afficher les articles filtrés`,
  nK = `Importer la page d'inscription`,
  rK = `Nom d'inscription`,
  iK = `Il s'agit du nom de la promotion auquel la page de participation fait référence et qu'elle utilise pour identifier les données à importer.`,
  aK = `Préfixe de l'étiquette`,
  oK = `Préfixe à ajouter aux étiquettes indiquées sur la page d'inscription. Cela permet par exemple de différencier l'étiquette «\xA0Action\xA0» indiquée sur la page d'inscription du tag du même nom sur la page du magasin.`,
  sK = `Démos requises`,
