  eq = `La description de l'évènement est déjà affichée dans une autre section. Voulez-vous vraiment faire apparaitre la description à cet endroit également\xA0?`,
  tq = `Les recommandations du groupe de curation sont déjà affichées dans une autre section. Voulez-vous vraiment faire apparaitre ces recommandations à cet endroit également\xA0?`,
  nq = `Vous avez déjà configuré une section pour afficher la diffusion en direct. Cette section sera ignorée.`,
  rq = `Toujours visible`,
  iq = `Visible uniquement le jour %1$s`,
  aq = `Visible uniquement le jour %1$s de %2$s à %3$s`,
  oq = `Visible le jour %1$s à partir de %2$s et les jours suivants`,
  sq = `Filtre\xA0:`,
  cq = `Afficher tous les articles`,
  lq = `Articles du jour %1$s uniquement (%2$s)`,
  uq = `Visibilité des nouveaux articles`,
  dq = `Définit la date pendant l'évènement promotionnel où les produits indiqués seront mis en vedette. Par défaut, ils seront mis en avant tous les jours, mais cette option peut être utilisée pour limiter la présence de certains produits à des jours précis.`,
  fq = `Arrière-plans quotidiens de l'évènement promotionnel`,
  pq = `La valeur par défaut 1 équivaut à un seul arrière-plan d'entête pour l'ensemble de l'évènement promotionnel. Une valeur plus élevée permet d'afficher des images différentes au fil des jours. L'image du dernier jour restera affichée, même après la fin de l'évènement. La durée de disponibilité des arrière-plans est basée sur celle de l'évènement, définie en nombre de jours dans l'onglet des options.`,
  mq = `%1$s entêtes de page promotionnelle`,
  hq = `Une seule image d'entête promotionnel pendant toute la durée de l'évènement`,
  gq = `Si vous modifiez ce paramètre, toutes les anciennes images d'entête promotionnel choisies seront supprimées. Voulez-vous vraiment continuer\xA0?`,
  _q = `Pour quel jour souhaitez-vous voir ou modifier l'image\xA0?`,
  vq = `L'aperçu affiche l'image téléchargée pour le jour choisi. Toute image associée à l'en-tête sera également affichée pour le jour actuellement sélectionné.`,
  yq = `Visible uniquement le jour %1$s de %2$s à %3$s`,
  bq = `Visible le jour %1$s à partir de %2$s et les jours suivants`,
