  kq = `Article non trouvé`,
  Aq = `Impossible de trouver des informations sur (%1$s %2$s). Il peut s'agir d'une faute de frappe, ou bien ceci n'est pas visible ou est masqué dans votre région.`,
  jq = `Non autorisé`,
  Mq = `Cet article ne peut pas être ajouté car sa page promotionnelle n'est liée à aucune page de conception (que ce soit pour les équipes de développement, d'édition ou de franchise). Pour actualiser l'association, veuillez créer un lien avec l'article puis recharger sa page promotionnelle.`,
  Nq = `Bundle non autorisé`,
  Pq = `Ce bundle ne peut pas être ajouté, car sa page promotionnelle n'est liée à aucune page de conception (que ce soit pour les équipes de développement, d'édition ou de franchise). Pour actualiser l'association, veuillez créer un lien avec l'article puis recharger sa page promotionnelle. Ces applications ne sont pas liées à la page de conception\xA0: (%1$s)`,
  Fq = `Package non autorisé`,
  Iq = `Ce package ne peut pas être ajouté, car sa page promotionnelle n'est liée à aucune page de conception (que ce soit pour les équipes de développement, d'édition ou de franchise). Pour actualiser l'association, veuillez créer un lien avec l'article puis recharger sa page promotionnelle. Ces applications ne sont pas liées à la page de conception\xA0: (%1$s)`,
  Lq = `Cet évènement est la duplication d'un évènement passé. Valve doit d'abord activer la fonctionnalité de la page promotionnelle pour que vous puissiez configurer cette page.`,
  Rq = `Page de promotion croisée`,
  zq = `Saisissez le GID de l'évènement promotionnel`,
  Bq = `Il s'agit de l'ID unique au bout de l'URL destiné à l'éditeur d'évènement partenaire. Seul l'ID de la page promotionnelle peut convenir ici. Consultez la documentation pour en savoir plus sur cette étape.`,
  Vq = `https://steamcommunity.com/groups/<nom de groupe>/partnerevents/edit/<Coller l'ID de ce groupe>`,
  Hq = `GID non valide, ne peut qu'être une valeur numérique`,
  Uq = `Page promotionnelle associée`,
  Wq = `L'évènement existe, mais le lien ne peut pas être créé pour le moment. La fonctionnalité promotionnelle n'est pas activée ou aucun jeu n'a été ajouté, il manque donc l'ID interne nécessaire à la création du lien. Veuillez demander à l'entité organisatrice de configurer la page promotionnelle puis réessayez de créer le lien.`,
  Gq = `Chargement des informations de la page promotionnelle…`,
  Kq = `La page promotionnelle n'est pas encore publiée ni visible.`,
  qq = `Titre de la page promotionnelle\xA0: %1$s`,
  Jq = `Cette page promotionnelle n'a pas d'image de capsule d'évènement`,
  Yq = `Sélection d'applications`,
  Xq = `Priorisez les listes de souhaits`,
  Zq = `Si la page de promotion croisée contient principalement des jeux à venir, il est probable qu'elle n'ait pas de données de revenus, auquel cas il est préférable d'opter pour un classement selon les listes de souhaits.`,
  Qq = `Prioriser par revenus`,
  $q = `Option par défaut. Utilise les informations de titres en promotion populaires pour prioriser les jeux que la clientèle verra depuis la page de promotion croisée.`,
  eJ = `S'il existe plus d'une page promotionnelle, la section se transforme en carrousel avec une diapositive par page, dans l'ordre affiché. Faites glisser les diapositives pour les réorganiser.`,
  tJ = `Ajouter une autre page promotionnelle`,
  nJ = `Éditeur de quantité limitée`,
  rJ = `Ajouter une option de quantité limitée`,
  iJ = `Modifier la description`,
  aJ = `Modifier la description en bas de section`,
