  cJ = `Package de matériel`,
  lJ = `Le package de matériel que la clientèle achète depuis ce bloc`,
  uJ = `Laissez le champ de description vide pour que cette option s'affiche en une seule ligne, avec le nom du package, son prix et le bouton «\xA0Acheter\xA0», sans image ni estimation de date de livraison.`,
  dJ = `Agencement`,
  fJ = `La grille regroupe en lignes des blocs de largeur fixe. La liste affiche un bloc par ligne, avec l'image à côté du texte.`,
  pJ = `Grille`,
  mJ = `Liste`,
  hJ = `Masquer les packages épuisés`,
  gJ = `Lorsque cette option est activée, un package qui n'a plus de stock est retiré de la section au lieu de s'afficher avec un bouton «\xA0En rupture de stock\xA0». Elle est désactivée par défaut.`,
  _J = `Couleurs des lignes compactes`,
  vJ = `S'appliquent aux options affichées sur une seule ligne (celles qui n'ont pas de description). Tout ce qui reste réglé sur «\xA0Par défaut\xA0» conserve l'apparence standard.`,
  yJ = `Nom`,
