  HJ = `En utilisant cette option, vous remplacerez les facettes existantes dans cette section. Voulez-vous vraiment continuer\xA0?`,
  UJ = `Utilisez une étiquette de fonctionnalité pour les applications auxquelles le tag du magasin «\xA0Contrôleur\xA0» a été appliqué.`,
  WJ = `Supprimer les facettes non utilisées`,
