  ZJ = `Par nom`,
  QJ = `Par nombre de correspondances`,
  $J = `Manuellement`,
  eY = `Nom de la valeur de facette. Il s'agit d'une option qu'on peut utiliser pour filtrer les jeux affichés dans cette section (par exemple\xA0:\xA0«\xA01ʳᵉ personne\xA0»).`,
  tY = `Facultatif\xA0:\xA0texte à afficher à droite de cette valeur de facette. Vous pouvez fournir une brève explication de la valeur de facette (par exemple\xA0:\xA0«\xA01\xA0à\xA02\xA0heures\xA0» pour une valeur de facette associée à des jeux à la durée de vie courte).`,
  nY = `Nom de cette facette. Chaque facette correspond à un groupe d'options connexes qui peuvent être utilisées pour filtrer les jeux affichés dans cette section (par exemple\xA0:\xA0«\xA0Genre\xA0»).`,
  rY = `Renseigner automatiquement les facettes et valeurs de facettes en fonction des catégories de tags appliqués aux jeux dans le magasin (par exemple\xA0:\xA0«\xA0Genre\xA0» et «\xA0Graphismes et perspective\xA0»). Vous pouvez modifier manuellement chaque facette et chaque valeur de facette au besoin.`,
  iY = `Supprimer les valeurs de facettes qui ne correspondent à aucun des articles de cette section.`,
  aY = `Quel est le nombre minimum de résultats souhaité pour chaque facette sélectionnée\xA0? Les termes du menu de gauche en dessous de cette valeur seront masqués. Le nombre est calculé en tenant compte des filtres des onglets. Un chiffre autour de 5 est un bon compromis.`,
  oY = `Limite le nombre maximum d'options à afficher pour chaque catégorie principale dans le menu de gauche. Par exemple, ne pas afficher plus de X\xA0genres dans la facette «\xA0Genre\xA0» (5 est un bon compromis).`,
  sY = `Pour chaque facette, trier les valeurs de facette en fonction de ce paramètre. Le tri par nombre de correspondances est recommandé.`,
  cY = `Dans chaque facette, trier les valeurs de facette par ordre alphabétique.`,
  lY = `Dans chaque facette, trier les valeurs de facette par ordre décroissant en fonction du nombre d'articles correspondants. Par exemple, dans une facette intitulée «\xA0Genre\xA0», la valeur de facette «\xA0RPG\xA0» apparaitra avant la valeur de facette «\xA0Stratégie\xA0» s'il y a plus de jeux RPG dans cette section que de jeux de stratégie.`,
  uY = `Ne pas trier les valeurs de facette. Elles seront affichées dans l'ordre indiqué dans les listes ci-dessous.`,
  dY = `Couleur des facettes mises en évidence`,
  fY = `Couleur d'entête`,
  pY = `Activé par défaut`,
  mY = `Synchroniser les 20\xA0tags du magasin les plus populaires`,
  hY = `Par défaut, seuls les 10\xA0tags du magasin les plus populaires sont synchronisés pour chaque article. Cochez cette case pour augmenter cette limite à 20\xA0tags.`,
  gY = `Générer les informations de débogage`,
  _Y = `ET logique`,
  vY = `Si la case est cochée, quand plusieurs valeurs de facettes sont sélectionnées pour cette facette, le ET logique des filtres de la facette sélectionnée est appliqué. Sinon, le OU logique des filtres de la facette sélectionnée est appliqué.`,
  yY = `Initialement développé`,
