  CY = `Définition de la source du ou des produits (facultatif)`,
  wY = `Au lieu d'indiquer une liste d'applications liées, vous pouvez renseigner le nom d'un hub de contenu. Cette section puisera alors uniquement tous ses éléments dans le hub de contenu et n'aura pas recours à la liste d'applications liées à cette promotion.`,
  TY = `Type de hub de contenu`,
  EY = `Catégorie`,
