  LY = `Items virtuels sélectionnés\xA0:`,
  RY = `Quantité maximale autorisée`,
  zY = `Il s'agit du nombre d'items virtuels de ce type qui peuvent être acheté en une seul fois. Pour désactiver le menu déroulant, définissez cette quantité sur 0 ou 1.`,
  BY = `Voir le magasin d'items de l'application`,
  VY = `Ajouter un item virtuel`,
  HY = `Vous pouvez choisir de charger une image pour remplacer l'image par défaut associée à l'item virtuel. Si vous ne le faites pas, nous utiliserons l'image qui s'affiche pour cet item virtuel dans le magasin d'items.`,
  UY = `Récupérer un item gratuit`,
  WY = `Cette section permet à un compte de récupérer un item gratuit, puis affiche ensuite la date à laquelle le prochain item gratuit sera disponible. Elle peut être utilisée pour distribuer des items quotidiennement. Elle est associée au widget de récompense pour configurer la récupération des items pour les évènements promotionnels.`,
  GY = `Facultatif\xA0: saisissez un nom pour le bouton de récupération.`,
