  pX = `DLC pour vous`,
  mX = `Affiche les DLC de tous les titres dans la bibliothèque de la personne. Cette section couvre tout le catalogue de Steam, et non pas seulement les articles mis en avant sur la page promotionnelle ou faisant partie de la liste des articles liés.`,
