  $X = `Aide de la communauté`,
  eZ = `Publiez un message ou cherchez une réponse à votre question dans les discussions Steam.`,
  tZ = `Consulter les discussions Steam`,
  nZ = `Titre de la page`,
  rZ = `Saisissez le titre de la FAQ ici`,
  iZ = `Contenu de la FAQ`,
  aZ = `Saisissez le BBCode de la FAQ ici`,
  oZ = `Modification d'une FAQ\xA0:`,
  sZ = `Aperçu de la FAQ\xA0:`,
  cZ = `La page est introuvable.`,
  lZ = `Accéder au tableau de bord`,
  uZ = `Sélectionnez un ou plusieurs fichiers pour importer des traductions pour votre titre et votre description. Nous utilisons les extensions des fichiers pour déterminer s'il s'agit d'un import de fichier XML ou CVS. Pour les fichiers XML, nous utilisons le code langue de l'API à la fin du nom du fichier (avant l'extension) pour déterminer la langue du contenu du fichier XML. Nous conseillons de commencer par exporter un fichier de traduction au format CSV ou XML pour vous assurer que vous travaillez avec le bon format.`,
  dZ = `Exporte la traduction actuelle en un fichier unique au format sélectionné. Avec le format XML, vous exportez la langue utilisée actuellement dans l'éditeur en un fichier unique. Avec le format CSV, vous exportez toutes les langues disponibles en un fichier unique.`,
  fZ = `Images`,
  pZ = `Modifier la FAQ`,
  mZ = `Supprimer la FAQ…`,
