  OZ = `Voir la FAQ publiée`,
  kZ = `Modifier le nom interne de la FAQ`,
  AZ = `Appuyez sur OK pour appliquer les modifications apportées au nom interne de la FAQ (visible uniquement des personnes qui ont les droits d'édition).`,
  jZ = `Publier…`,
  MZ = `Publiez le contenu en une ou plusieurs langues. Remarque\xA0: le paramètre de visibilité n'est pas lié à la publication.`,
