  PZ = `Publication de la FAQ en cours. Veuillez patienter…`,
  FZ = `La FAQ a été publiée\xA0!`,
  IZ = `À la publication, le brouillon d'une FAQ devient sa version publique. Des modifications ont été apportées aux brouillons des langues ci-après. Choisissez les brouillons que vous souhaitez publier maintenant.`,
  LZ = `Remarque\xA0: publier une FAQ ne la rend pas visible pour autant. Vous devez indiquer sa visibilité sur les différents territoires séparément.`,
  RZ = `Erreur de chargement\xA0: il manque des informations sur une publication antérieure nécessaires pour publier le document. Veuillez réactualiser la page.`,
